<?php require_once __DIR__.'/../../app/layout.php';$m=require_member();$p=$pdo->prepare('SELECT * FROM membership_payments WHERE member_id=? ORDER BY created_at DESC');$p->execute([$m['id']]);$payments=$p->fetchAll();$d=$pdo->prepare('SELECT * FROM donations WHERE member_id=? ORDER BY created_at DESC');$d->execute([$m['id']]);$donations=$d->fetchAll();$n=$pdo->prepare("SELECT * FROM notices WHERE status='active' AND audience IN ('members','both') AND publish_date<=CURDATE() AND (expiry_date IS NULL OR expiry_date>=CURDATE()) ORDER BY publish_date DESC");$n->execute();header_html('Member dashboard');?><h1>Welcome, <?=e($m['full_name'])?></h1><section class="grid"><article class="card"><b>Member ID</b><p><?=e($m['member_id'])?></p></article><article class="card"><b>Membership status</b><p><?=e(ucfirst($m['status']))?></p></article><article class="card"><b>Membership fee</b><p><?=e(setting($pdo,'membership_fee','0'))?> · <?=e(setting($pdo,'membership_validity',''))?></p></article></section><p class="actions"><a class="button" href="/member/payment.php">Submit membership payment</a><a class="button" href="/member/donation.php">Make donation</a><a class="button" href="/member/profile.php">Update profile</a><a class="button" href="/member/logout.php">Logout</a></p><h2>Payment history</h2><table><tr><th>Type</th><th>Amount</th><th>Status</th><th>Acknowledgement</th></tr><?php foreach(array_merge($payments,$donations) as $r):$type=isset($r['purpose'])?'donation':'membership';$q=$pdo->prepare('SELECT id FROM acknowledgements WHERE payment_type=? AND source_id=?');$q->execute([$type,$r['id']]);$aid=$q->fetchColumn();?><tr><td><?=e(ucfirst($type))?></td><td><?=e($r['amount'])?></td><td><?=e($r['status'])?></td><td><?php if($aid):?><a href="/receipt.php?id=<?=$aid?>">View / print</a><?php endif;?></td></tr><?php endforeach;?></table><h2>Notices</h2><?php foreach($n->fetchAll() as $row):?><article class="card"><b><?=e($row['title'])?></b><p><?=e($row['description'])?></p></article><?php endforeach;footer_html();
